mapper.select:
SELECT * FROM gb_distributer_goods


        AND gb_dg_distributer_id = #{disId}


        AND gb_dg_nx_father_id = #{nxFatherId}


        AND gb_dg_dfg_goods_father_id = #{dgFatherId}


        AND gb_dg_gb_supplier_id = #{supplierId}


ORDER BY gb_distributer_goods_id

SELECT gdg.*, IFNULL(stockStats.goodsStockTotal, 0) AS goodsStockTotal, IFNULL(stockStats.goodsStockWeightTotal, 0) AS goodsStockWeightTotal FROM gb_distributer_goods AS gdg LEFT JOIN ( SELECT gb_dgs_gb_dis_goods_id, SUM(gb_dgs_rest_subtotal) AS goodsStockTotal, SUM(gb_dgs_rest_weight) AS goodsStockWeightTotal FROM gb_department_goods_stock WHERE gb_dgs_rest_weight > 0 GROUP BY gb_dgs_gb_dis_goods_id ) AS stockStats ON stockStats.gb_dgs_gb_dis_goods_id = gdg.gb_distributer_goods_id
AND gdg.gb_dg_distributer_id = #{disId}
AND gdg.gb_dg_control_price = #{price}
AND gdg.gb_dg_control_fresh = #{fresh}
AND gdg.gb_dg_gb_department_id = #{toDepId}
AND gdg.gb_dg_dfg_goods_father_id = #{fatherId}
AND ( gdg.gb_dg_goods_name LIKE CONCAT('%', #{searchStr}, '%') OR gdg.gb_dg_goods_brand LIKE CONCAT('%', #{searchStr}, '%') OR gdg.gb_dg_goods_pinyin LIKE CONCAT('%', #{searchPinyin}, '%') OR gdg.gb_dg_goods_py LIKE CONCAT('%', #{searchPinyin}, '%') )
ORDER BY gdg.gb_dg_goods_sort, gdg.gb_dg_goods_sons_sort
